55	+        csv.append(header()).append('\n');
56	+        for (String row : rows(selected)) {
57	+            csv.append(row).append('\n');
58	+        }
59	+        csv.append("total,").append(total(selected)).append('\n');
60	+        return csv.toString();
61	+    }
