  2	CREATE TABLE rooms (
  3	    number       integer PRIMARY KEY,
  4	    type         text NOT NULL,
  5	    capacity     integer NOT NULL CHECK (capacity > 0),
  6	    nightly_rate numeric(10, 2) NOT NULL CHECK (nightly_rate > 0)
  7	);
